






























































































































































































































































































































import { Component, Vue } from "vue-property-decorator";

import { Model } from "survey-vue";

import showdown from "showdown";

import ActionButtonBar from "@/components/ActionButtonBar.vue";
import Result from "@/components/Result.vue";
import Obligations from "@/components/Obligations.vue";
import SurveyFile from "@/interfaces/SurveyFile";
import i18n from "@/plugins/i18n";
import surveyJSON from "@/survey-enfr.json";
import RiskArea from "@/interfaces/RiskArea";
import {
  fetchSurveyFileFromUrl,
  getSourceJsonUrl
} from "@/utils/remoteSurveyFile";
import { hydrateSurveyModel, normalizeSurveyFile } from "@/utils/surveyFile";
import { loadSurveyDefinition } from "@/utils/surveyVersions";
import { elementToMarkdown } from "@/utils/markdownExport";

declare global {
  interface Window {
    saveMarkdownFile: any;
  }
}

@Component({
  components: {
    ActionButtonBar,
    Result,
    Obligations
  },
  computed: {
    score: function() {
      return this.$store.getters.calcScore;
    }
  }
})
export default class Results extends Vue {
  loadingMessage = "";
  loadError = "";
  loadedJsonUrl = "";
  loadedVersion = "";
  initializingFromUrl = false;

  get myResults(): any[][] {
    const sections = this.$store.getters.resultDataSections;
    return Array.isArray(sections) ? sections : [[], [], [], []];
  }

  get resultsReady(): boolean {
    return (
      !this.initializingFromUrl &&
      !this.loadError &&
      Boolean(this.$store.state.result)
    );
  }

  get loadErrorHeading(): string {
    return this.$i18n.locale === "fr"
      ? "Impossible de charger les données demandées."
      : "The requested data could not be loaded.";
  }

  get loadedMessage(): string {
    return this.$i18n.locale === "fr"
      ? "Résultats EIA chargés depuis :"
      : "AIA results loaded from:";
  }

  get displayVersion(): string {
    return String(
      this.loadedVersion ||
        this.$store.state.version ||
        this.Survey.version ||
        ""
    ).replace(/^v/, "");
  }

  riskAreaFields = [
    { key: "risk_area", label: this.$t("riskArea").toString() },
    { key: "no_of_questions", label: this.$t("noOfQuestions").toString() },
    { key: "project_score", label: this.$t("projectScore").toString() },
    { key: "maximum_score", label: this.$t("maximumScore").toString() }
  ];

  mitigationFields = [
    { key: "risk_area", label: this.$t("mitigationArea").toString() },
    { key: "no_of_questions", label: this.$t("noOfQuestions").toString() },
    { key: "project_score", label: this.$t("projectScore").toString() },
    { key: "maximum_score", label: this.$t("maximumScore").toString() }
  ];

  riskAreaItems() {
    let items: RiskArea[] = [];
    let totalNoQuestions = 0;
    let totalProjectScore = 0;
    let totalMaxScore = 0;
    if (this.myResults[1]?.length > 0) {
      this.myResults[1].forEach((myResult: any) => {
        if (myResult.questionHeader !== undefined) {
          let riskAreaTitle = myResult.questionHeader;
          let riskAreaName = myResult.name.replace(/\d/g, "");
          let sectionScore = this.$store.getters.getScoreBySection(
            riskAreaName
          );
          items.push({
            risk_area: riskAreaTitle[this.$i18n.locale],
            no_of_questions: sectionScore[0],
            project_score: sectionScore[1],
            maximum_score: sectionScore[2]
          });
          totalNoQuestions += sectionScore[0];
          totalProjectScore += sectionScore[1];
          totalMaxScore += sectionScore[2];
        }
      });
    }
    items.push({
      risk_area: this.$t("rawRiskScore")
        .toString()
        .toUpperCase(),
      no_of_questions: totalNoQuestions,
      project_score: totalProjectScore,
      maximum_score: totalMaxScore
    });
    return items;
  }

  mitigationItems() {
    let items: RiskArea[] = [];
    let totalNoQuestions = 0;
    let totalProjectScore = 0;
    let totalMaxScore = 0;
    if (this.myResults[2]?.length > 0) {
      this.myResults[2].forEach((myResult: any) => {
        if (myResult.questionHeader !== undefined) {
          let riskAreaTitle = myResult.questionHeader;
          let riskAreaName = myResult.name.replace(/\d/, "");
          let sectionScore = this.$store.getters.getScoreBySection(
            riskAreaName
          );
          items.push({
            risk_area: riskAreaTitle[this.$i18n.locale]
              ? riskAreaTitle[this.$i18n.locale]
              : riskAreaTitle["en"],
            no_of_questions: sectionScore[0],
            project_score: sectionScore[1],
            maximum_score: sectionScore[2]
          });
          totalNoQuestions += sectionScore[0];
          totalProjectScore += sectionScore[1];
          totalMaxScore += sectionScore[2];
        }
      });
    }
    items.push({
      risk_area: this.$t("mitigationScore")
        .toString()
        .toUpperCase(),
      no_of_questions: totalNoQuestions,
      project_score: totalProjectScore,
      maximum_score: totalMaxScore
    });
    return items;
  }

  Survey: Model = this.$store.state.result || new Model(surveyJSON);

  startAgain() {
    this.Survey.clear(true, true);
    window.localStorage.clear();
    this.$store.commit("resetSurvey");
    this.$router.push({ path: "/" });
  }

  exportStructuredData() {
    (this.$refs.actionButtonBar as ActionButtonBar).saveSurvey();
  }

  exportMarkdown(locale: "en" | "fr") {
    const content = document.getElementById(`${locale}-content`);
    if (!content) return;
    const blob = new Blob([elementToMarkdown(content)], {
      type: "text/markdown"
    });
    window.saveMarkdownFile(`aia-results-${locale}.md`, blob);
  }

  async fileLoaded($event: SurveyFile) {
    this.loadingMessage =
      this.$i18n.locale === "fr"
        ? "Chargement des résultats EIA…"
        : "Loading AIA results…";
    this.loadError = "";
    this.loadedJsonUrl = "";
    try {
      const loadedFile = normalizeSurveyFile($event);
      const loadedSurvey = await loadSurveyDefinition(loadedFile.version);
      const model = new Model(loadedSurvey.definition);
      this.configureSurvey(model);
      loadedFile.version = loadedSurvey.version;
      hydrateSurveyModel(model, loadedFile);
      this.Survey = model;
      this.loadedVersion = loadedSurvey.version;
      this.$store.commit("resetSurvey");
      this.$store.commit("setSurveyVersion", loadedSurvey.version);
      this.$store.commit("updateResult", model);
    } catch (error) {
      this.loadError = error instanceof Error ? error.message : String(error);
    } finally {
      this.loadingMessage = "";
    }
  }

  private configureSurvey(survey: Model) {
    survey.onComplete.add(result => {
      this.$store.commit("updateResult", result);
    });

    survey.onComplete.add(() => {
      this.$router.push("Results");
    });

    survey.onValueChanged.add(result => {
      this.$store.commit("updateResult", result);
    });

    const converter = new showdown.Converter();

    survey.onTextMarkdown.add(function(sender, options) {
      //convert the markdown text to html
      var str = converter.makeHtml(options.text);
      //remove root paragraphs <p></p>
      str = str.substring(3);
      str = str.substring(0, str.length - 4);
      //set html
      options.html = str;
    });

    // Set locale
    survey.locale = i18n.locale;

    // Remove the default required '*'.
    survey.requiredText = "";

    // Fix all the question labels as they're using <H5> instead of <label>
    // as SurveyJS has open issue as per: https://github.com/surveyjs/surveyjs/issues/928
    survey.onAfterRenderQuestion.add(function(sender, options) {
      let title = options.htmlElement.getElementsByTagName("H5")[0];
      if (title) {
        var questionRequiredHTML = "";

        if (options.question.isRequired) {
          // Should do localization mechanism
          var requiredText = sender.locale == "fr" ? "obligatoire" : "required";
          questionRequiredHTML =
            ' <strong class="required">(' + requiredText + ")</strong>";
        }

        title.outerHTML =
          '<label for="' +
          options.question.inputId +
          '" class="' +
          title.className +
          '"><span class="field-name">' +
          title.innerText +
          "</span>" +
          questionRequiredHTML +
          "</label>";
      }
    });
  }

  private queryJsonUrl(): string {
    const value = this.$route.query.json;
    if (Array.isArray(value)) return String(value[0] || "");
    return String(value || "");
  }

  private async initializeFromUrl(jsonUrl: string) {
    this.initializingFromUrl = true;
    this.loadingMessage =
      this.$i18n.locale === "fr"
        ? "Chargement des résultats EIA à partir de l’URL…"
        : "Loading AIA results from the URL…";
    this.loadError = "";
    try {
      const loadedFile = await fetchSurveyFileFromUrl(jsonUrl);
      await this.fileLoaded(loadedFile);
      if (!this.loadError) this.loadedJsonUrl = getSourceJsonUrl(jsonUrl);
    } catch (error) {
      this.loadError = error instanceof Error ? error.message : String(error);
    } finally {
      this.loadingMessage = "";
      this.initializingFromUrl = false;
    }
  }

  created() {
    if (this.$store.state.result) {
      this.Survey = this.$store.state.result;
    }
    this.configureSurvey(this.Survey);

    const jsonUrl = this.queryJsonUrl();
    if (jsonUrl) {
      this.initializeFromUrl(jsonUrl);
    } else if (!this.$store.state.result && this.$store.getters.inProgress) {
      this.fileLoaded({
        version: this.$store.state.version,
        currentPage: this.$store.state.currentPageNo,
        data: this.$store.state.toolData,
        translationsOnResult: this.$store.state.translationsOnResult
      } as SurveyFile);
    }
  }
}
